import{_ as s,C as n,o as r,c as i,aj as e,G as o}from"./chunks/framework.BwH0p-pt.js";const f=JSON.parse('{"title":"Magic AI — Platforms","description":"","frontmatter":{},"headers":[],"relativePath":"2.1/magic-ai/platforms.md","filePath":"2.1/magic-ai/platforms.md","lastUpdated":1781079046000}'),l={name:"2.1/magic-ai/platforms.md"};function d(p,t,m,g,c,h){const a=n("ImagePopup");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="magic-ai-—-platforms" tabindex="-1">Magic AI — Platforms <a class="header-anchor" href="#magic-ai-—-platforms" aria-label="Permalink to &quot;Magic AI — Platforms&quot;">​</a></h1><blockquote><p><strong>Sidebar:</strong> Magic AI → <strong>Platforms</strong><strong>URL:</strong> <code>/admin/magic-ai/platforms</code></p></blockquote><p>The <strong>Platforms</strong> page is where you register the AI providers UnoPim is allowed to talk to. Without at least one active platform, every other Magic AI feature — wand icons, auto-translation, auto-enrichment, and the AI Agent Chat — stays switched off.</p><h2 id="what-is-a-platform" tabindex="-1">What is a Platform? <a class="header-anchor" href="#what-is-a-platform" aria-label="Permalink to &quot;What is a Platform?&quot;">​</a></h2><p>A <em>Platform</em> is one configured provider connection. It has three parts:</p><ol><li><strong>Provider</strong> — the company whose AI you want to use (OpenAI, Anthropic, Gemini, Ollama, Groq, <strong>Custom</strong>, etc.).</li><li><strong>API key</strong> — the secret that authorises UnoPim to call that provider&#39;s API.</li><li><strong>Enabled models</strong> — which of the provider&#39;s models should be available inside UnoPim.</li></ol><p>You can register <strong>as many Platforms as you like</strong>. A common setup is one premium provider for content (e.g., OpenAI <code>gpt-4o</code>) and a cheaper or faster one for translation (e.g., Gemini <code>gemini-1.5-flash</code>). The Platforms page keeps them side by side; the <strong>Settings</strong> page decides which Platform handles which capability.</p><div class="tip custom-block"><p class="custom-block-title">Custom Provider</p><p>Need to call an OpenAI-compatible service that isn&#39;t on the preset list — for example a self-hosted gateway, a corporate proxy, or an alternative inference provider? Pick the <strong>Custom</strong> provider and supply your own <strong>Base URL</strong>. UnoPim will route requests through the same <code>LaravelAiAdapter</code> pipeline used for the built-in providers.</p></div><h2 id="what-does-this-page-do" tabindex="-1">What does this page do? <a class="header-anchor" href="#what-does-this-page-do" aria-label="Permalink to &quot;What does this page do?&quot;">​</a></h2><ul><li>Lists every Platform you&#39;ve registered, along with its status and models.</li><li>Lets you <strong>add</strong>, <strong>edit</strong>, <strong>enable/disable</strong>, <strong>delete</strong>, and <strong>set a default</strong> Platform.</li><li>Encrypts every API key on save — keys are never stored in plain text and are masked in the UI.</li></ul>',10)),o(a,{src:"/assets/2.1/images/magic-ai/ai-platforms.png",alt:"AI Platforms"}),t[1]||(t[1]=e('<h2 id="platforms-datagrid" tabindex="-1">Platforms datagrid <a class="header-anchor" href="#platforms-datagrid" aria-label="Permalink to &quot;Platforms datagrid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>The name you assigned to the platform configuration.</td></tr><tr><td><strong>Provider</strong></td><td>The AI provider (OpenAI, Anthropic, Gemini, Ollama, Groq, etc.).</td></tr><tr><td><strong>Models</strong></td><td>The models enabled for this platform.</td></tr><tr><td><strong>Default</strong></td><td>Whether this platform is the default (Yes/No).</td></tr><tr><td><strong>Status</strong></td><td>Enabled or Disabled.</td></tr><tr><td><strong>Created At</strong></td><td>Date the platform was added.</td></tr><tr><td><strong>Actions</strong></td><td>Star (set as default), Edit (pencil icon), Delete (trash icon).</td></tr></tbody></table><h2 id="adding-a-platform" tabindex="-1">Adding a Platform <a class="header-anchor" href="#adding-a-platform" aria-label="Permalink to &quot;Adding a Platform&quot;">​</a></h2><p>Click the <strong>Add Platform</strong> button in the top-right corner. A modal opens with the following fields:</p><ol><li><strong>Provider</strong> — Select from the dropdown (OpenAI, Anthropic, Gemini, Ollama, Groq, <strong>Custom</strong>, etc.).</li><li><strong>Label</strong> — A descriptive name such as <em>&quot;OpenAI Production&quot;</em> or <em>&quot;Gemini Translation&quot;</em>. This is what you&#39;ll see in the Settings dropdowns.</li><li><strong>Base URL</strong> <em>(Custom provider only)</em> — The OpenAI-compatible endpoint to call (e.g., <code>https://gateway.example.com/v1</code>). Only shown when <strong>Provider = Custom</strong>.</li><li><strong>API Key</strong> — Paste the key from your provider account. It&#39;s encrypted before it hits the database.</li><li><strong>Models</strong> — Multi-select the models you want to expose. Only the models you tick here appear in the downstream Text / Image / Translation / Agentic PIM dropdowns on the Settings page.</li><li><strong>Status</strong> — Toggle to enable or disable the platform.</li></ol>',5)),o(a,{src:"/assets/2.1/images/magic-ai/add-platform.png",alt:"Add Platform"}),t[2]||(t[2]=e(`<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>API credentials are stored with encrypted credential storage for security. Your API keys are never stored in plain text.</p></div><h3 id="test-connection" tabindex="-1">Test Connection <a class="header-anchor" href="#test-connection" aria-label="Permalink to &quot;Test Connection&quot;">​</a></h3><p>After saving, use the <strong>Test Connection</strong> action on the platform row to verify credentials before relying on it. The test is powered by the new <strong>ModelRecommender</strong>, which:</p><ul><li>Picks a text-capable model from your enabled list (image-only models are skipped, so they don&#39;t return a false-negative).</li><li>Sends a small probe request against the provider.</li><li>Reports a clear pass/fail. If it fails, the <a href="./../ai-agent/">PrismErrorResolver</a> translates the underlying provider error into a user-friendly message (invalid key, rate limit, model unavailable, etc.).</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Run Test Connection any time you rotate an API key, change the Base URL of a Custom provider, or tick a new model — it&#39;s the fastest way to confirm the platform is healthy without opening the AI Agent Chat.</p></div><h2 id="platform-actions" tabindex="-1">Platform Actions <a class="header-anchor" href="#platform-actions" aria-label="Permalink to &quot;Platform Actions&quot;">​</a></h2><ul><li><strong>Star icon</strong> — Sets the platform as the <strong>default</strong>. Anywhere the Settings page shows <em>&quot;Use Default Platform&quot;</em>, it resolves to the starred platform. Only one can be the default at a time.</li><li><strong>Test Connection</strong> — Validates credentials, the Base URL (for Custom providers), and at least one usable text model. Image-only models are skipped automatically.</li><li><strong>Pencil icon</strong> — Opens the edit modal so you can update the label, rotate the API key, adjust the model list, or flip status.</li><li><strong>Trash icon</strong> — Deletes the platform configuration. Any feature that still points at this platform in Settings falls back to the default. Irreversible.</li></ul><h2 id="how-platform-selection-flows-into-features" tabindex="-1">How Platform selection flows into features <a class="header-anchor" href="#how-platform-selection-flows-into-features" aria-label="Permalink to &quot;How Platform selection flows into features&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Platforms (provider + key + models)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Settings (pick platform + model per feature)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► Text Generation ──► Wand icons on text fields</span></span>
<span class="line"><span>        ├─► Image Generation ──► Wand icons on image/gallery fields</span></span>
<span class="line"><span>        ├─► Translation ──────► Auto-translate on save + bulk command</span></span>
<span class="line"><span>        └─► Agentic PIM ──────► AI Agent Chat</span></span></code></pre></div><p>Every request — from a single field generation to a complex AI Agent plan — follows the <strong>Agentic PIM Pipeline</strong>:</p>`,10)),o(a,{src:"/assets/2.1/images/ai-agent/agentic-pim-pipeline.png",alt:"Agentic PIM Pipeline — 5-Step Workflow"}),t[3]||(t[3]=e('<h2 id="minimum-setup" tabindex="-1">Minimum setup <a class="header-anchor" href="#minimum-setup" aria-label="Permalink to &quot;Minimum setup&quot;">​</a></h2><p>To get any Magic AI feature working at all:</p><ol><li>Register at least <strong>one</strong> Platform.</li><li>Make sure it has at least <strong>one</strong> Model enabled.</li><li>Set its Status to <strong>Enabled</strong>.</li><li><strong>Star</strong> one Platform as the default.</li></ol><p>Once that&#39;s done, head to <strong>Magic AI → Settings</strong> to route each capability (Text / Image / Translation / Agentic PIM) to a Platform and Model of your choice.</p>',4))])}const P=s(l,[["render",d]]);export{f as __pageData,P as default};
